arguments.content:
:root {
  --primary: #0051C3;
  --primary-hover: #003e99;
  --accent: #DE5052;
  --accent-hover: #c44345;
  --text-dark: #1E293B;
  --text-light: #64748B;
  --bg-main: #FFFFFF;
  --bg-alt: #F8FAFC;
  --border-light: #E2E8F0;

  --font-heading: 'Poppins', sans-serif;
  --font-body: 'Open Sans', sans-serif;

  --transition: all 0.3s ease;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--text-dark);
  background-color: var(--bg-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-dark);
  margin-bottom: 1rem;
}

a {
  text-decoration: none;
  color: var(--primary);
  transition: var(--transition);
}

a:hover {
  color: var(--primary-hover);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Layout Utilities */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-alt {
  background-color: var(--bg-alt);
}

.text-center { text-align: center; }
.text-primary { color: var(--primary); }
.text-accent { color: var(--accent); }

.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }
.mb-5 { margin-bottom: 3rem; }

/* Grid Layout */
.grid {
  display: grid;
  gap: 2rem;
}
.grid-2 { grid-template-columns: repeat(1, 1fr); }
.grid-3 { grid-template-columns: repeat(1, 1fr); }
.grid-4 { grid-template-columns: repeat(1, 1fr); }

@media (min-width: 768px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  font-family: var(--font-heading);
  font-weight: 500;
  text-align: center;
  cursor: pointer;
  border: none;
  transition: var(--transition);
}

.btn-primary {
  background-color: var(--primary);
  color: #fff;
}
.btn-primary:hover {
  background-color: var(--primary-hover);
  color: #fff;
}

.btn-accent {
  background-color: var(--accent);
  color: #fff;
}
.btn-accent:hover {
  background-color: var(--accent-hover);
  color: #fff;
}

.btn-outline {
  background-color: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
}
.btn-outline:hover {
  background-color: var(--primary);
  color: #fff;
}

/* Navigation */
.navbar {
  background-color: var(--bg-main);
  border-bottom: 1px solid var(--border-light);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-links {
  display: none;
  gap: 2rem;
  align-items: center;
}

.nav-links a {
  color: var(--text-dark);
  font-weight: 500;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--primary);
}

.mobile-menu-btn {
  display: block;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: var(--text-dark);
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }
  .mobile-menu-btn {
    display: none;
  }
}

/* Mobile Nav Drawer */
.mobile-nav-drawer {
  position: fixed;
  top: 80px;
  left: 0;
  width: 100%;
  height: calc(100vh - 80px);
  background-color: var(--bg-main);
  padding: 2rem;
  transform: translateX(-100%);
  transition: transform 0.3s ease-in-out;
  z-index: 999;
}

.mobile-nav-drawer.open {
  transform: translateX(0);
}

.mobile-nav-drawer a {
  display: block;
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
  color: var(--text-dark);
}

/* Hero Section */
.hero {
  padding: 6rem 0;
  text-align: center;
}

.hero h1 {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-light);
  max-width: 800px;
  margin: 0 auto 2rem;
}

.hero-cta {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

@media (min-width: 768px) {
  .hero h1 {
    font-size: 3.5rem;
  }
  .hero p {
    font-size: 1.25rem;
  }
}

/* Cards */
.card {
  background-color: var(--bg-main);
  border-radius: var(--radius);
  padding: 2rem;
  border: 1px solid var(--border-light);
  transition: var(--transition);
}

.card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  background-color: var(--bg-alt);
  color: var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

/* Stats Banner */
.stats-banner {
  background-color: var(--primary);
  color: #fff;
  padding: 4rem 0;
}

.stat-item h3 {
  font-size: 2.5rem;
  color: #fff;
  margin-bottom: 0.5rem;
}

.stat-item p {
  font-size: 1.125rem;
  opacity: 0.9;
}

/* Testimonials Carousel */
.testimonial-container {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease-in-out;
}

.testimonial-slide {
  min-width: 100%;
  padding: 2rem;
  background-color: var(--bg-alt);
  border-radius: var(--radius);
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  color: var(--text-dark);
}

.testimonial-author {
  font-weight: 600;
}

.testimonial-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  background: var(--bg-main);
  border: 1px solid var(--border-light);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.carousel-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* Pricing Table */
.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--border-light);
  transition: .4s;
  border-radius: 34px;
}

.slider:before {
  position: absolute;
  content: "";
  height: 26px;
  width: 26px;
  left: 4px;
  bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}

input:checked + .slider {
  background-color: var(--primary);
}

input:checked + .slider:before {
  transform: translateX(26px);
}

.pricing-card {
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  padding: 2rem;
  background-color: var(--bg-main);
  text-align: center;
  display: flex;
  flex-direction: column;
}

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow);
  transform: scale(1.02);
  position: relative;
}

.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 20px;
  font-size: 0.875rem;
  font-weight: 600;
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text-dark);
  margin: 1rem 0;
}

.pricing-price span {
  font-size: 1rem;
  color: var(--text-light);
  font-weight: 400;
}

.pricing-features {
  list-style: none;
  text-align: left;
  margin: 2rem 0;
  flex-grow: 1;
}

.pricing-features li {
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pricing-features li svg {
  color: var(--primary);
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 1rem;
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
  color: var(--text-light);
}

.faq-item.active .faq-answer {
  max-height: 200px;
  padding-bottom: 1rem;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-question svg {
  transition: transform 0.3s ease;
}

/* Contact Form */
.form-group {
  margin-bottom: 1.5rem;
  text-align: left;
}

.form-label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  font-family: var(--font-body);
  font-size: 1rem;
  transition: border-color 0.3s;
}

.form-control:focus {
  outline: none;
  border-color: var(--primary);
}

.error-message {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}

.form-group.error .form-control {
  border-color: var(--accent);
}

.form-group.error .error-message {
  display: block;
}

.success-message {
  display: none;
  background-color: #dcfce7;
  color: #166534;
  padding: 1rem;
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  text-align: center;
}

/* Footer */
.footer {
  background-color: var(--text-dark);
  color: #fff;
  padding: 4rem 0 2rem;
}

.footer h4 {
  color: #fff;
  margin-bottom: 1.5rem;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: 0.75rem;
}

.footer-links a {
  color: #cbd5e1;
}

.footer-links a:hover {
  color: #fff;
}

.footer-bottom {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid #334155;
  text-align: center;
  color: #cbd5e1;
}

/* CTA Block */
.cta-block {
  background-color: var(--bg-alt);
  text-align: center;
  padding: 6rem 0;
}

.cta-block h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Nav Toggle
  const mobileMenuBtn = document.getElementById('mobileMenuBtn');
  const mobileNavDrawer = document.getElementById('mobileNavDrawer');

  if (mobileMenuBtn && mobileNavDrawer) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileNavDrawer.classList.toggle('open');
    });
  }

  // Testimonial Carousel
  const track = document.getElementById('testimonialTrack');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');

  if (track && prevBtn && nextBtn) {
    let currentIndex = 0;
    const slides = document.querySelectorAll('.testimonial-slide');
    const totalSlides = slides.length;

    const updateSlide = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    nextBtn.addEventListener('click', () => {
      currentIndex = (currentIndex + 1) % totalSlides;
      updateSlide();
    });

    prevBtn.addEventListener('click', () => {
      currentIndex = (currentIndex - 1 + totalSlides) % totalSlides;
      updateSlide();
    });
  }

  // Pricing Toggle
  const pricingToggle = document.getElementById('billingToggle');
  const starterPrice = document.getElementById('starterPrice');
  const premiumPrice = document.getElementById('premiumPrice');

  if (pricingToggle && starterPrice && premiumPrice) {
    // Annual saves 20%
    const monthlyStarter = 29.99;
    const monthlyPremium = 69.99;
    const annualStarter = (monthlyStarter * 0.8).toFixed(2);
    const annualPremium = (monthlyPremium * 0.8).toFixed(2);

    pricingToggle.addEventListener('change', (e) => {
      if (e.target.checked) {
        // Annual
        starterPrice.innerHTML = `$${annualStarter}<span>/mo</span>`;
        premiumPrice.innerHTML = `$${annualPremium}<span>/mo</span>`;
      } else {
        // Monthly
        starterPrice.innerHTML = `$${monthlyStarter}<span>/mo</span>`;
        premiumPrice.innerHTML = `$${monthlyPremium}<span>/mo</span>`;
      }
    });
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  if (faqItems.length > 0) {
    faqItems.forEach(item => {
      const question = item.querySelector('.faq-question');
      question.addEventListener('click', () => {
        // Close others
        faqItems.forEach(otherItem => {
          if (otherItem !== item) {
            otherItem.classList.remove('active');
          }
        });
        // Toggle current
        item.classList.toggle('active');
      });
    });
  }

  // Contact Form Validation
  const contactForm = document.getElementById('contactForm');
  const successMessage = document.getElementById('successMessage');

  if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let isValid = true;

      const fields = ['name', 'email', 'company', 'locations', 'message'];

      fields.forEach(field => {
        const input = document.getElementById(field);
        const group = input.closest('.form-group');
        if (!input.value.trim()) {
          group.classList.add('error');
          isValid = false;
        } else {
          group.classList.remove('error');
          // Basic email validation
          if (field === 'email' && !/\S+@\S+\.\S+/.test(input.value)) {
            group.classList.add('error');
            group.querySelector('.error-message').innerText = "Please enter a valid email address.";
            isValid = false;
          }
        }
      });

      if (isValid) {
        contactForm.style.display = 'none';
        successMessage.style.display = 'block';
      }
    });

    // Clear error on input
    const inputs = contactForm.querySelectorAll('.form-control');
    inputs.forEach(input => {
      input.addEventListener('input', () => {
        input.closest('.form-group').classList.remove('error');
      });
    });
  }
});
